}

/** ai-model-picker (SURF-370, REQ-SURF-173): model Combobox grouped by
 * provider, capability Badges and context-window counts. Options come from
 * the app's route that proxies Kiro Prism GET /v1/models — see fixtures.ts. */
export function ModelPicker({ options, value, onValueChange, 'aria-label': ariaLabel = 'Model' }: ModelPickerProps) {
  const byProvider = React.useMemo(() => {
    const groups = new Map<string, ModelOption[]>();
    for (const o of options) {
      const list = groups.get(o.provider) ?? [];
      list.push(o);
      groups.set(o.provider, list);
    }
    return groups;
  }, [options]);
  const items = React.useMemo(() => options.map((o) => o.id), [options]);
  return (
    <Combobox.Root
      value={value}
      onValueChange={(v: unknown) => onValueChange?.(String(v))}
      items={items}
    >
      <Combobox.Input aria-label={ariaLabel} placeholder="Search models" />
      <Combobox.Trigger aria-label={ariaLabel}>
        {options.find((o) => o.id === value)?.label ?? 'Select model'}
      </Combobox.Trigger>
      <Combobox.Content data-ag-part="model-picker">
        <Combobox.Empty>No models</Combobox.Empty>
        {Array.from(byProvider.entries()).map(([provider, opts]) => (
          <React.Fragment key={provider}>
            <div role="presentation" data-ag-part="model-provider">{provider}</div>
            {opts.map((o) => (
              <Combobox.Item key={o.id} value={o.id} data-ag-part="model-option">
                <span>{o.label}</span>
                {o.contextWindow !== undefined ? (
                  <span data-ag-part="model-context">{Math.round(o.contextWindow / 1000)}k</span>
                ) : null}
                {(o.capabilities ?? []).map((c) => <Badge key={c}>{c}</Badge>)}
              </Combobox.Item>
            ))}
          </React.Fragment>
        ))}
      </Combobox.Content>
    </Combobox.Root>
  );
}

/* ai-sdk-adapter (SURF-390, REQ-SURF-106/170): wraps @ai-sdk/react `useChat`
 * and returns ready-made props for ./ai — `{ threadProps: { messages },
 * composerProps: { onSubmit, onStop }, status }`. Requires the consumer's
 * `ai` + `@ai-sdk/react` dependencies (declared in registry-item.json). */
'use client';
import { useChat } from '@ai-sdk/react';
import type { ChatTransport, UIMessage } from 'ai';
import type { AgMessage } from 'aura-glass/ai';

export interface UseAuraChatOptions {
  /** Transport — e.g. `new DefaultChatTransport({ api: '/api/chat' })`. */
  transport?: ChatTransport<UIMessage>;
  messages?: UIMessage[];
}

export interface UseAuraChatResult {
  threadProps: { messages: AgMessage[] };
  composerProps: {
    onSubmit: (payload: { text: string; files: File[] }) => void;
    onStop?: (() => void) | undefined;
  };
  status: 'submitted' | 'streaming' | 'ready' | 'error';
}

export function useAuraChat(options: UseAuraChatOptions = {}): UseAuraChatResult {
  const chat = useChat<UIMessage>({
    ...(options.transport ? { transport: options.transport } : {}),
    ...(options.messages ? { messages: options.messages } : {}),
  });
  const streaming = chat.status === 'streaming' || chat.status === 'submitted';
  return {
    threadProps: { messages: chat.messages as AgMessage[] },
    composerProps: {
      onSubmit: ({ text }) => {
        void chat.sendMessage({ text });
      },
      ...(streaming ? { onStop: () => { void chat.stop(); } } : {}),
    },
    status: chat.status,
  };
}

'use client';
import * as React from 'react';
import { TreeView } from 'aura-glass/data';
import type { AgStep } from 'aura-glass/ai';

export interface TraceTreeProps {
  steps: readonly AgStep[];
  /** Total run duration in ms for the duration bars; defaults to the sum of
   * top-level step durations. */
  totalMs?: number | undefined;
  renderDetail?: ((step: AgStep) => React.ReactNode) | undefined;
  'aria-label'?: string | undefined;
}

interface TraceItem extends Record<string, unknown> {
  step: AgStep;
}

const STATE_ICON: Record<string, string> = {
  queued: '○', running: '◌', 'needs-approval': '⚠', succeeded: '✓', failed: '✕', denied: '⊘', skipped: '—',
};

/** ai-trace-tree (SURF-372, REQ-SURF-173): AgStep trees on W2 TreeView with a
 * duration bar per span (width = span/total, min 2px) plus the text duration
 * and state icon. */
export function TraceTree({ steps, totalMs, renderDetail, 'aria-label': ariaLabel = 'Trace' }: TraceTreeProps) {
  const total = totalMs ?? steps.reduce((n, s) => n + (s.endedAt != null && s.startedAt != null ? s.endedAt - s.startedAt : 0), 0);
  const items = React.useMemo<TraceItem[]>(() => steps.map((step) => ({ step })), [steps]);
  return (
    <div data-ag-part="trace-tree" data-total-ms={total}>
      <TreeView<TraceItem>
        items={items}
        getKey={(i: TraceItem) => i.step.id}
        getChildren={(i: TraceItem) => i.step.children?.map((c: AgStep) => ({ step: c }))}
        getTextValue={(i: TraceItem) => i.step.label}
        aria-label={ariaLabel}
        renderItem={(i: TraceItem) => {
          const span = i.step.endedAt != null && i.step.startedAt != null ? i.step.endedAt - i.step.startedAt : null;
          const pct = span != null && total > 0 ? Math.max((span / total) * 100, 2 / Math.max(total, 1)) : 0;
          return (
            <span data-ag-part="trace-node" data-state={i.step.state}>
              <span aria-hidden="true" data-ag-part="trace-icon">{STATE_ICON[i.step.state] ?? '•'}</span>
              <span data-ag-part="trace-label">{i.step.label}</span>
              {span != null ? (
                <>
                  <span
                    data-ag-part="trace-duration-bar"
                    role="presentation"
                    style={{ display: 'inline-block', blockSize: '4px', minInlineSize: '2px', inlineSize: `${pct}%`, background: 'currentColor', opacity: 0.35 }}
                  />
                  <span data-ag-part="trace-duration">{span} ms</span>
                </>
              ) : null}
              {renderDetail ? <span data-ag-part="trace-detail">{renderDetail(i.step)}</span> : null}
            </span>
          );
        }}
      />
    </div>
  );
}

'use client';
import * as React from 'react';
import { Composer } from 'aura-glass/ai';

export interface VoiceInputActionProps {
  /** Called with the recorded audio File (built from dataavailable chunks,
   * mimeType taken from the recorder). The consumer transcribes it. */
  onFile?: ((file: File) => void) | undefined;
  disabled?: boolean | undefined;
  'aria-label'?: string | undefined;
}

type VoiceState = 'idle' | 'recording' | 'unsupported' | 'denied';

/** ai-voice-input (SURF-374, REQ-SURF-170/173): Composer.Action using a real
 * MediaRecorder. getUserMedia prompts for mic permission; the recording state
 * is announced; stop produces a File from the recorded chunks. Browsers
 * without MediaRecorder/getUserMedia get an explicit unsupported state — no
 * mock capture path. */
export function VoiceInputAction({ onFile, disabled, 'aria-label': ariaLabel = 'Voice input' }: VoiceInputActionProps) {
  const [state, setState] = React.useState<VoiceState>(() =>
    typeof navigator !== 'undefined' && 'mediaDevices' in navigator && 'MediaRecorder' in globalThis ? 'idle' : 'unsupported');
  const recorderRef = React.useRef<MediaRecorder | null>(null);
  const chunksRef = React.useRef<Blob[]>([]);

  const stop = React.useCallback(() => {
    const rec = recorderRef.current;
    if (rec && rec.state !== 'inactive') rec.stop();
  }, []);

  const start = React.useCallback(async () => {
    if (state === 'unsupported') return;
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      const rec = new MediaRecorder(stream);
      chunksRef.current = [];
      rec.addEventListener('dataavailable', (e) => {
        if (e.data.size > 0) chunksRef.current.push(e.data);
      });
      rec.addEventListener('stop', () => {
        stream.getTracks().forEach((t) => t.stop());
        const blob = new Blob(chunksRef.current, { type: rec.mimeType });
        onFile?.(new File([blob], 'voice-input.webm', { type: rec.mimeType }));
        setState('idle');
      }, { once: true });
      recorderRef.current = rec;
      rec.start();
      setState('recording');
    } catch {
      setState('denied');
    }
  }, [state, onFile]);

  return (
    <Composer.Action
      aria-label={ariaLabel}
      aria-pressed={state === 'recording'}
      disabled={disabled === true || state === 'unsupported'}
      data-ag-part="voice-input"
      data-state={state}
      title={state === 'unsupported' ? 'Voice input is not supported in this browser' : ariaLabel}
      onClick={state === 'recording' ? stop : () => { void start(); }}
    >
      <svg viewBox="0 0 16 16" width="16" height="16" aria-hidden="true"><path d="M8 1a2 2 0 0 0-2 2v4a2 2 0 0 0 4 0V3a2 2 0 0 0-2-2Zm-5 6a5 5 0 0 0 4 4.9V14H5.5a.5.5 0 0 0 0 1h5a.5.5 0 0 0 0-1H9v-2.1A5 5 0 0 0 13 7h-1a4 4 0 0 1-8 0Z" fill="currentColor"/></svg>
      <span data-ag-part="voice-state" aria-live="polite">
        {state === 'recording' ? 'Recording' : state === 'denied' ? 'Microphone blocked' : state === 'unsupported' ? 'Unsupported' : ''}
      </span>
    </Composer.Action>
  );
}

